-- 463_intake_xjz_skill_effect_csharp_evidence.sql
-- Purpose: ingest C# restored skill, buff, pet-skill, monster-skill, and runtime capture evidence as readable Traditional Chinese server research tables.
-- Source pack: XJZ-csharp-evidence-capture-pack-20260818.zip

DROP TABLE IF EXISTS god2_research._xjz_stage_skill_effect_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_buff_effect_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_effect_definition;
DROP TABLE IF EXISTS god2_research._xjz_stage_character_god_skill_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_combat_pet_skill_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_monster_skill_probe_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_skill_runtime_capture_target;
DROP TABLE IF EXISTS god2_research._xjz_stage_skill_runtime_playbook_route;
DROP TABLE IF EXISTS god2_research._xjz_stage_skill_effect_service_catalog_template;

CREATE TABLE god2_research._xjz_stage_skill_effect_rule (rule_id INT PRIMARY KEY, source_kind VARCHAR(96) NOT NULL, effect_index INT NULL, effect_category VARCHAR(96) NULL, effect_code VARCHAR(160) NULL, base_value INT NULL, description_zh_tw TEXT NULL, rule_kind VARCHAR(96) NOT NULL, target_scope VARCHAR(96) NULL, element_zh_tw VARCHAR(64) NULL, status_zh_tw VARCHAR(96) NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1, UNIQUE KEY uq_stage_skill_effect (source_kind, effect_index, effect_code, base_value, description_zh_tw(255))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_buff_effect_rule (rule_id INT PRIMARY KEY, source_kind VARCHAR(96) NOT NULL, effect_index INT NULL, effect_code VARCHAR(160) NULL, base_value INT NULL, buff_kind VARCHAR(96) NOT NULL, stat_zh_tw VARCHAR(96) NULL, element_zh_tw VARCHAR(64) NULL, status_zh_tw VARCHAR(96) NULL, description_zh_tw TEXT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1, UNIQUE KEY uq_stage_buff_effect (source_kind, effect_index, effect_code, base_value, description_zh_tw(255))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_effect_definition (id INT PRIMARY KEY, source_kind VARCHAR(96) NOT NULL, effect_index INT NULL, effect_category VARCHAR(96) NULL, effect_code VARCHAR(255) NULL, base_value INT NULL, description_zh_tw TEXT NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0, UNIQUE KEY uq_stage_effect_definition (source_kind, effect_index, effect_code, base_value, description_zh_tw(255))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_character_god_skill_template (skill_item_id INT PRIMARY KEY, skill_code VARCHAR(96) NULL, name_zh_tw VARCHAR(160) NOT NULL, class_text_zh_tw VARCHAR(160) NULL, skill_family_zh_tw VARCHAR(160) NULL, skill_tier INT NULL, mp_cost INT NULL, attack_range INT NULL, target_scope_zh_tw VARCHAR(96) NULL, power_text_zh_tw TEXT NULL, effect_code VARCHAR(160) NULL, actor_skill_kind VARCHAR(96) NOT NULL, source_menu_name VARCHAR(96) NOT NULL, raw_description_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_combat_pet_skill_template (pet_skill_template_id INT PRIMARY KEY, design_option_id INT NULL, option_group_id INT NOT NULL, option_group_zh_tw VARCHAR(160) NOT NULL, option_index INT NOT NULL, content_zh_tw TEXT NOT NULL, skill_rule_kind VARCHAR(96) NOT NULL, skill_rule_value INT NULL, price INT NOT NULL DEFAULT 0, icon_code INT NULL, actor_skill_kind VARCHAR(96) NOT NULL, raw_json LONGTEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0, UNIQUE KEY uq_stage_pet_skill_design (design_option_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_monster_skill_probe_template (probe_id INT PRIMARY KEY, monster_code INT NOT NULL, monster_name_zh_tw VARCHAR(160) NOT NULL, field_rom_path VARCHAR(255) NULL, battle_rom_path VARCHAR(255) NULL, actor_skill_kind VARCHAR(96) NOT NULL, wanted_field VARCHAR(160) NOT NULL, capture_target_table VARCHAR(128) NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1, UNIQUE KEY uq_stage_monster_skill_probe (monster_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_skill_runtime_capture_target (target_id INT PRIMARY KEY, actor_skill_kind VARCHAR(96) NOT NULL, source_template_table VARCHAR(128) NOT NULL, source_template_id INT NOT NULL, skill_item_id INT NULL, skill_id INT NULL, skill_name_zh_tw VARCHAR(160) NOT NULL, skill_code VARCHAR(96) NULL, class_text_zh_tw VARCHAR(160) NULL, skill_family_zh_tw VARCHAR(160) NULL, skill_tier INT NULL, mp_cost INT NULL, attack_range INT NULL, target_scope_zh_tw VARCHAR(96) NULL, effect_code VARCHAR(160) NULL, pet_template_id INT NULL, monster_code INT NULL, monster_name_zh_tw VARCHAR(160) NULL, capture_priority VARCHAR(32) NOT NULL, capture_context VARCHAR(128) NOT NULL, wanted_fields_json LONGTEXT NOT NULL, target_state_table VARCHAR(128) NOT NULL, target_event_table VARCHAR(128) NOT NULL, target_sample_table VARCHAR(128) NOT NULL, request_hint_zh_tw TEXT NOT NULL, current_client_source TEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_skill_runtime_playbook_route (route_binding_id INT PRIMARY KEY, target_id INT NOT NULL, step_id INT NOT NULL, action_key VARCHAR(96) NOT NULL, actor_skill_kind VARCHAR(96) NOT NULL, source_template_table VARCHAR(128) NOT NULL, source_template_id INT NOT NULL, skill_item_id INT NULL, skill_id INT NULL, skill_name_zh_tw VARCHAR(160) NOT NULL, effect_code VARCHAR(160) NULL, capture_context VARCHAR(128) NOT NULL, target_table VARCHAR(128) NOT NULL, target_table_role VARCHAR(128) NOT NULL, target_state_table VARCHAR(128) NOT NULL, target_event_table VARCHAR(128) NOT NULL, target_sample_table VARCHAR(128) NOT NULL, route_id INT NOT NULL, query_id INT NOT NULL, required_run_key VARCHAR(96) NOT NULL, sample_count_sql TEXT NOT NULL, last_sample_id_sql TEXT NULL, presence_sql TEXT NOT NULL, route_state VARCHAR(64) NOT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1, UNIQUE KEY uq_stage_skill_runtime_route (target_id, route_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_skill_effect_service_catalog_template (service_id INT PRIMARY KEY, catalog_key VARCHAR(96) NOT NULL UNIQUE, skill_book_template_count INT NOT NULL DEFAULT 0, character_god_skill_template_count INT NOT NULL DEFAULT 0, combat_pet_skill_template_count INT NOT NULL DEFAULT 0, monster_skill_probe_template_count INT NOT NULL DEFAULT 0, skill_runtime_capture_target_count INT NOT NULL DEFAULT 0, skill_runtime_playbook_route_count INT NOT NULL DEFAULT 0, effect_definition_count INT NOT NULL DEFAULT 0, skill_effect_rule_count INT NOT NULL DEFAULT 0, buff_effect_rule_count INT NOT NULL DEFAULT 0, combat_formula_sample_count INT NOT NULL DEFAULT 0, combat_formula_stage_sample_count INT NOT NULL DEFAULT 0, combat_formula_inference_count INT NOT NULL DEFAULT 0, combat_event_log_count INT NOT NULL DEFAULT 0, actor_skill_kind_summary_json LONGTEXT NOT NULL, source_template_summary_json LONGTEXT NOT NULL, route_table_summary_json LONGTEXT NOT NULL, effect_source_summary_json LONGTEXT NOT NULL, skill_rule_kind_summary_json LONGTEXT NOT NULL, buff_kind_summary_json LONGTEXT NOT NULL, sample_tables_json LONGTEXT NOT NULL, raw_source TEXT NOT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS god2_research.xjz_skill_effect_rules_csharp;
CREATE TABLE god2_research.xjz_skill_effect_rules_csharp AS
SELECT rule_id, source_kind, effect_index, effect_category, effect_code, base_value, description_zh_tw, rule_kind, target_scope, element_zh_tw, status_zh_tw,
       raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '技能效果規則：服務端可用來把效果碼分類成傷害、治療、狀態、屬性或特殊修正候選。' AS game_function_zh_tw,
       CASE WHEN packet_evidence_boundary = 1 THEN '需用官方戰鬥封包確認實際公式、倍率、命中與持續回合。' ELSE '靜態效果定義可先供服務端分類與顯示。' END AS server_apply_note_zh_tw
FROM god2_research._xjz_stage_skill_effect_rule;
ALTER TABLE god2_research.xjz_skill_effect_rules_csharp ADD PRIMARY KEY (rule_id);

DROP TABLE IF EXISTS god2_research.xjz_buff_effect_rules_csharp;
CREATE TABLE god2_research.xjz_buff_effect_rules_csharp AS
SELECT rule_id, source_kind, effect_index, effect_code, base_value, buff_kind, stat_zh_tw, element_zh_tw, status_zh_tw, description_zh_tw,
       raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       'BUFF/DEBUFF 效果規則：服務端可用來對照能力增減、五行、狀態異常與特殊狀態候選。' AS game_function_zh_tw,
       CASE WHEN packet_evidence_boundary = 1 THEN '需用官方封包或黑箱測試確認加成倍率與持續回合。' ELSE '靜態 BUFF 類型可先供服務端分類。' END AS server_apply_note_zh_tw
FROM god2_research._xjz_stage_buff_effect_rule;
ALTER TABLE god2_research.xjz_buff_effect_rules_csharp ADD PRIMARY KEY (rule_id);

DROP TABLE IF EXISTS god2_research.xjz_effect_definitions_csharp;
CREATE TABLE god2_research.xjz_effect_definitions_csharp AS
SELECT id, source_kind, effect_index, effect_category, effect_code, base_value, description_zh_tw,
       raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '效果資源定義：服務端可用來對照技能/神仙/特效資源與效果代碼。' AS game_function_zh_tw
FROM god2_research._xjz_stage_effect_definition;
ALTER TABLE god2_research.xjz_effect_definitions_csharp ADD PRIMARY KEY (id);

DROP TABLE IF EXISTS god2_research.xjz_character_god_skill_templates_csharp;
CREATE TABLE god2_research.xjz_character_god_skill_templates_csharp AS
SELECT c.skill_item_id, i.item_id AS formal_item_id, c.skill_code, c.name_zh_tw, c.class_text_zh_tw, c.skill_family_zh_tw, c.skill_tier, c.mp_cost, c.attack_range, c.target_scope_zh_tw, c.power_text_zh_tw, c.effect_code, c.actor_skill_kind, c.source_menu_name,
       c.raw_source AS source_file, c.raw_line AS source_line, c.evidence_status, c.packet_evidence_boundary,
       '角色/神仙技能書：服務端可用來建立技能名稱、職業、系別、階級、MP 消耗、射程與目標範圍。' AS game_function_zh_tw,
       '技能效果數值需再串接效果規則與官方施放樣本；這裡先落技能模板與消耗/範圍。' AS server_apply_note_zh_tw
FROM god2_research._xjz_stage_character_god_skill_template c
LEFT JOIN god2_game.items i ON i.client_item_id = c.skill_item_id;
ALTER TABLE god2_research.xjz_character_god_skill_templates_csharp ADD PRIMARY KEY (skill_item_id);

DROP TABLE IF EXISTS god2_research.xjz_combat_pet_skill_templates_csharp;
CREATE TABLE god2_research.xjz_combat_pet_skill_templates_csharp AS
SELECT pet_skill_template_id, design_option_id, option_group_id, option_group_zh_tw, option_index, content_zh_tw, skill_rule_kind, skill_rule_value, price, icon_code, actor_skill_kind,
       raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '戰鬥寵技能：服務端可用來對照寵物技能選項、價格、圖示與技能規則值。' AS game_function_zh_tw,
       '寵物技能實戰效果仍需戰鬥封包確認；此表先補寵物技能選項資料。' AS server_apply_note_zh_tw
FROM god2_research._xjz_stage_combat_pet_skill_template;
ALTER TABLE god2_research.xjz_combat_pet_skill_templates_csharp ADD PRIMARY KEY (pet_skill_template_id);

DROP TABLE IF EXISTS god2_research.xjz_monster_skill_probe_templates_csharp;
CREATE TABLE god2_research.xjz_monster_skill_probe_templates_csharp AS
SELECT probe_id, monster_code, monster_name_zh_tw, field_rom_path, battle_rom_path, actor_skill_kind, wanted_field, capture_target_table,
       raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '怪物技能探針：服務端可用來列出哪些怪物需要抓技能槽、技能效果、MP 與戰鬥行為。' AS game_function_zh_tw,
       '這是怪物技能與怪物 MP 的重要補證入口；需正式戰鬥封包或記憶體快照回填。' AS server_apply_note_zh_tw
FROM god2_research._xjz_stage_monster_skill_probe_template;
ALTER TABLE god2_research.xjz_monster_skill_probe_templates_csharp ADD PRIMARY KEY (probe_id), ADD UNIQUE KEY uq_xjz_monster_skill_probe_templates_csharp (monster_code);

DROP TABLE IF EXISTS god2_research.xjz_skill_runtime_capture_targets_csharp;
CREATE TABLE god2_research.xjz_skill_runtime_capture_targets_csharp AS
SELECT target_id, actor_skill_kind, source_template_table, source_template_id, skill_item_id, skill_id, skill_name_zh_tw, skill_code, class_text_zh_tw, skill_family_zh_tw, skill_tier, mp_cost, attack_range, target_scope_zh_tw, effect_code, pet_template_id, monster_code, monster_name_zh_tw, capture_priority, capture_context,
       'character_id, skill_item_id, skill_id, skill_level, mp_before, mp_after, target_scope, hit_result, damage_or_heal_amount, status_result, effect_code, combat_event_json, raw_packet' AS wanted_fields_zh_tw,
       target_state_table, target_event_table, target_sample_table, request_hint_zh_tw, current_client_source, raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '技能施放抓包目標：用來確認 MP 消耗、命中、傷害/補血、BUFF/DEBUFF、狀態與原始封包。' AS game_function_zh_tw
FROM god2_research._xjz_stage_skill_runtime_capture_target;
ALTER TABLE god2_research.xjz_skill_runtime_capture_targets_csharp ADD PRIMARY KEY (target_id);

DROP TABLE IF EXISTS god2_research.xjz_skill_runtime_playbook_routes_csharp;
CREATE TABLE god2_research.xjz_skill_runtime_playbook_routes_csharp AS
SELECT route_binding_id, target_id, step_id, action_key, actor_skill_kind, source_template_table, source_template_id, skill_item_id, skill_id, skill_name_zh_tw, effect_code, capture_context, target_table, target_table_role, target_state_table, target_event_table, target_sample_table, route_id, query_id, required_run_key, route_state, evidence_status, packet_evidence_boundary,
       '技能施放 Playbook 路線：正式抓包時用來確認各技能是否已取得樣本。' AS game_function_zh_tw
FROM god2_research._xjz_stage_skill_runtime_playbook_route;
ALTER TABLE god2_research.xjz_skill_runtime_playbook_routes_csharp ADD PRIMARY KEY (route_binding_id), ADD UNIQUE KEY uq_xjz_skill_runtime_playbook_routes_csharp (target_id, route_id);

DROP TABLE IF EXISTS god2_research.xjz_skill_effect_service_catalog_csharp;
CREATE TABLE god2_research.xjz_skill_effect_service_catalog_csharp AS
SELECT service_id, catalog_key, skill_book_template_count, character_god_skill_template_count, combat_pet_skill_template_count, monster_skill_probe_template_count, skill_runtime_capture_target_count, skill_runtime_playbook_route_count, effect_definition_count, skill_effect_rule_count, buff_effect_rule_count, combat_formula_sample_count, combat_formula_stage_sample_count, combat_formula_inference_count, combat_event_log_count,
       raw_source AS source_file, evidence_status, packet_evidence_boundary,
       '技能/BUFF/戰鬥公式服務目錄：服務端用來看目前技能證據量、抓包量與公式樣本缺口。' AS game_function_zh_tw
FROM god2_research._xjz_stage_skill_effect_service_catalog_template;
ALTER TABLE god2_research.xjz_skill_effect_service_catalog_csharp ADD PRIMARY KEY (service_id), ADD UNIQUE KEY uq_xjz_skill_effect_service_catalog_csharp (catalog_key);

DROP TABLE IF EXISTS god2_research.xjz_skill_related_item_rule_gaps_csharp;
CREATE TABLE god2_research.xjz_skill_related_item_rule_gaps_csharp (
  gap_key VARCHAR(96) NOT NULL PRIMARY KEY,
  game_function_zh_tw VARCHAR(160) NOT NULL,
  evidence_status_zh_tw VARCHAR(160) NOT NULL,
  server_apply_note_zh_tw VARCHAR(512) NOT NULL,
  next_capture_action_zh_tw VARCHAR(512) NOT NULL,
  source_pack_id VARCHAR(96) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP VIEW IF EXISTS god2_research.vw_xjz_skill_effect_csharp_summary_zh_tw;
CREATE VIEW god2_research.vw_xjz_skill_effect_csharp_summary_zh_tw AS
SELECT '技能效果規則' AS evidence_area_zh_tw, COUNT(*) AS row_count, SUM(packet_evidence_boundary = 1) AS needs_packet_count, '技能效果候選分類' AS game_function_zh_tw FROM god2_research.xjz_skill_effect_rules_csharp
UNION ALL SELECT 'BUFF效果規則', COUNT(*), SUM(packet_evidence_boundary = 1), '能力增減/五行/狀態候選' FROM god2_research.xjz_buff_effect_rules_csharp
UNION ALL SELECT '效果資源定義', COUNT(*), SUM(packet_evidence_boundary = 1), '技能與特效資源對照' FROM god2_research.xjz_effect_definitions_csharp
UNION ALL SELECT '角色/神仙技能模板', COUNT(*), SUM(packet_evidence_boundary = 1), '技能書、MP、射程、範圍' FROM god2_research.xjz_character_god_skill_templates_csharp
UNION ALL SELECT '戰鬥寵技能模板', COUNT(*), SUM(packet_evidence_boundary = 1), '寵物技能選項與規則值' FROM god2_research.xjz_combat_pet_skill_templates_csharp
UNION ALL SELECT '怪物技能探針', COUNT(*), SUM(packet_evidence_boundary = 1), '怪物技能槽/MP/戰鬥行為補證' FROM god2_research.xjz_monster_skill_probe_templates_csharp
UNION ALL SELECT '技能施放抓包目標', COUNT(*), SUM(packet_evidence_boundary = 1), '技能 MP/命中/傷害/狀態封包補證' FROM god2_research.xjz_skill_runtime_capture_targets_csharp
UNION ALL SELECT '技能Playbook路線', COUNT(*), SUM(packet_evidence_boundary = 1), '正式技能抓包路線' FROM god2_research.xjz_skill_runtime_playbook_routes_csharp
UNION ALL SELECT '技能相關道具缺口', COUNT(*), COUNT(*), '道具使用效果缺證' FROM god2_research.xjz_skill_related_item_rule_gaps_csharp;

DROP VIEW IF EXISTS god2_research.vw_xjz_skill_effect_mingsi_candidates_zh_tw;
CREATE VIEW god2_research.vw_xjz_skill_effect_mingsi_candidates_zh_tw AS
SELECT skill_item_id, skill_code, name_zh_tw, class_text_zh_tw, skill_family_zh_tw, skill_tier, mp_cost, attack_range, target_scope_zh_tw, power_text_zh_tw, effect_code, evidence_status,
       '冥思/仙道被動候選查詢：若此視圖為空，代表 C# 還原包技能模板未直接出現「冥思」名稱，需要另由客戶端表或實機測試補證。' AS note_zh_tw
FROM god2_research.xjz_character_god_skill_templates_csharp
WHERE name_zh_tw LIKE '%冥思%' OR skill_family_zh_tw LIKE '%冥思%' OR class_text_zh_tw LIKE '%仙道%';

DROP VIEW IF EXISTS god2_research.vw_xjz_skill_effect_text_quality_zh_tw;
CREATE VIEW god2_research.vw_xjz_skill_effect_text_quality_zh_tw AS
SELECT '技能效果規則' AS table_zh_tw, SUM(COALESCE(description_zh_tw, '') REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]') AS suspicious_text_count FROM god2_research.xjz_skill_effect_rules_csharp
UNION ALL SELECT 'BUFF效果規則', SUM(COALESCE(description_zh_tw, '') REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]') FROM god2_research.xjz_buff_effect_rules_csharp
UNION ALL SELECT '角色/神仙技能模板', SUM(name_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]' OR COALESCE(class_text_zh_tw, '') REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]' OR COALESCE(skill_family_zh_tw, '') REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]' OR COALESCE(target_scope_zh_tw, '') REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]') FROM god2_research.xjz_character_god_skill_templates_csharp
UNION ALL SELECT '戰鬥寵技能模板', SUM(option_group_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]' OR content_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]') FROM god2_research.xjz_combat_pet_skill_templates_csharp
UNION ALL SELECT '怪物技能探針', SUM(monster_name_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]') FROM god2_research.xjz_monster_skill_probe_templates_csharp
UNION ALL SELECT '技能施放抓包目標', SUM(skill_name_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]' OR COALESCE(request_hint_zh_tw, '') REGEXP '[绁诲嫏鎺湜鍦锛攻击术两围圆]') FROM god2_research.xjz_skill_runtime_capture_targets_csharp;

UPDATE god2_research.xjz_csharp_apply_queue
SET safe_apply_level_zh_tw = '已匯入研究表與抓包目標，不直接寫死未知公式',
    next_server_action_zh_tw = '技能模板、BUFF 規則、寵物技能、怪物技能探針與技能施放抓包路線已整理；後續用官方封包/黑箱測試確認公式、倍率、持續回合與怪物 MP。',
